/* ---------- workspace store (no clinical copies) ---------- */
function dpSt(){if(DP.st)return DP.st;let s: any=null;try{s=JSON.parse(localStorage.getItem(DP_KEY)||"null")}catch(e){}if(!s||s.v!==1)s={v:1,cur:"",recents:[],notes:{},period:"6m",rtab:"sum"};DP.st=s;return s}
function dpSave(){clearTimeout(DP.t);DP.t=setTimeout(()=>{try{localStorage.setItem(DP_KEY,JSON.stringify(DP.st))}catch(e){}},120)}
function dpReload(){DP.st=null;dpSt()}
const dpLocale=()=>({fr:"fr-FR",en:"en-GB",de:"de-DE",ar:"ar-u-nu-latn"}[true?lang():"fr"]||"fr-FR");
function dpD(iso?: A,o?: A){if(!iso)return "—";const s=String(iso);if(/^\d{4}$/.test(s))return s;const d=new Date(s.length<=10?s+"T12:00:00":s);if(isNaN(+d))return s;try{return new (Intl as any).DateTimeFormat(dpLocale(),o||{day:"2-digit",month:"2-digit",year:"numeric"}).format(d)}catch(e){return s.slice(0,10)}}
const dpT=(ms?: A)=>{try{return new (Intl as any).DateTimeFormat(dpLocale(),Object.assign({hour:"2-digit",minute:"2-digit"},typeof CL_ORG_TZ!=="undefined"?{timeZone:CL_ORG_TZ}:{})).format(new Date(ms))}catch(e){return ""}};/* v93: organisation time, as in Calendar */
const dpToday=()=>typeof paToday==="function"?paToday():new Date().toISOString().slice(0,10);
function dpRel(iso?: A){if(!iso)return "";const a=new Date(String(iso).slice(0,10)+"T12:00:00"),b=new Date(dpToday()+"T12:00:00");const n=Math.round((+a-+b)/864e5);try{const rtf=new (Intl as any).RelativeTimeFormat(dpLocale(),{numeric:"auto"});const A=Math.abs(n);if(A<14)return rtf.format(n,"day");if(A<60)return rtf.format(Math.round(n/7),"week");if(A<730)return rtf.format(Math.round(n/30.4),"month");return rtf.format(Math.round(n/365),"year")}catch(e){return dpD(iso)}}
function dpNum(v?: A,d=1){try{return new (Intl as any).NumberFormat(dpLocale(),{maximumFractionDigits:d}).format(v)}catch(e){return String(v)}}
const dpHue=(s?: A)=>{let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))%360;return h};

/* ---------- read adapters over the owning domains ---------- */
const dpOk=()=>typeof paSt==="function";
function dpPats(){try{return paSt().pats.filter((p?: A)=>p.status!=="merged")}catch(e){return []}}
function dpCur(){const S=dpSt();let p=S.cur&&paFind(S.cur);if(!p||p.status==="merged"){p=dpPats().find((x?: A)=>x.status==="active")||dpPats()[0]||null;if(p){S.cur=p.id;dpSave()}}return p}
const dpClin=(p?: A)=>{try{return paClinOk(p)}catch(e){return false}};
const dpLive=(a?: A)=>a&&a.status!=="error";
function dpLead(p?: A){const t=(p.team||[]).filter((t?: A)=>!t.to||t.to>=dpToday());const l=t.find((x?: A)=>x.lead)||t[0];return l?{pr:l.pr,name:rmPracName(l.pr),job:rmPracJob(l.pr)||l.role||"",role:l.role}:null}
function dpAppts(p?: A,from?: A,to?: A){try{clReload?.()}catch(e){}try{return clItems(from,to).filter((a?: A)=>a.pid===p.id).sort((a?: A,b?: A)=>a.start<b.start?-1:1)}catch(e){return []}}
function dpUpcoming(p?: A,n?: A){const now=Date.now();return dpAppts(p,now-36e5*3,now+365*864e5).filter((a?: A)=>CL_ACTIVE(a.status)&&a.status!=="completed"&&Date.parse(a.end)>=now).slice(0,n||50)}
function dpPast(p?: A,days?: A){const now=Date.now();return dpAppts(p,now-(days||365)*864e5,now).filter((a?: A)=>Date.parse(a.start)<now).reverse()}
const dpSvcName=(id?: A)=>{try{return clSvcName(id)}catch(e){return "—"}};
function dpVisit(a?: A){try{if(typeof cbStage!=="function")return null;return cbStage(a)}catch(e){return null}}
function dpAllergies(p?: A){return p.clin.allergies.filter((a?: A)=>dpLive(a)&&a.status!=="inactive"&&a.status!=="resolved")}
function dpMeds(p?: A){return p.clin.meds.filter((m?: A)=>dpLive(m)&&m.status!=="stopped"&&(!m.end||m.end>=dpToday()))}
function dpProblems(p?: A){return p.clin.problems.filter(dpLive).sort((a?: A,b?: A)=>+(a.status==="resolved")-+(b.status==="resolved")||String(b.onset||"").localeCompare(String(a.onset||"")))}
function dpDocs(p?: A){try{return p.docs.filter((d?: A)=>d.status!=="deleted"&&paDocCanSee(p,d)).sort((a?: A,b?: A)=>String(b.d).localeCompare(String(a.d)))}catch(e){return []}}
const DP_PER: A={"3m":92,"6m":183,"12m":366,all:36500};
function dpObs(p?: A,code?: A,per?: A){const lim=DP_PER[per||dpSt().period]||183;const from=paAdd(dpToday(),-lim);return p.clin.obs.filter((o?: A)=>dpLive(o)&&o.code===code&&String(o.ts).slice(0,10)>=from).sort((a?: A,b?: A)=>String(a.ts).localeCompare(String(b.ts)))}
function dpBmiSeries(p?: A,per?: A){const hs=p.clin.obs.filter((o?: A)=>dpLive(o)&&o.code==="height").sort((a?: A,b?: A)=>String(a.ts).localeCompare(String(b.ts)));if(!hs.length)return [];return dpObs(p,"weight",per).map((w?: A)=>{const h=[...hs].reverse().find(x=>x.ts<=w.ts)||hs[0];const m=+h.v/100;return {ts:w.ts,v:Math.round(+w.v/(m*m)*10)/10,calc:true}})}
function dpCompleteness(p?: A){try{return paCompleteness(p)}catch(e){return {pct:0,miss:[]}}}
function dpBilling(p?: A){try{return paBilling(p)}catch(e){return {state:"unavailable"}}}
function dpMoney(v?: A,cur?: A){try{return new (Intl as any).NumberFormat(dpLocale(),{style:"currency",currency:cur||"EUR"}).format(v)}catch(e){return v+" "+(cur||"€")}}

/* smart, factual flags — never a clinical judgement */
function dpFlags(p?: A){const out=[];const clin=dpClin(p);const T=dpToday();
  if(clin){const crit=dpAllergies(p).filter((a?: A)=>a.crit==="high");if(crit.length)out.push({lvl:"bad",ic:"alert",t:L4("Allergie à criticité élevée enregistrée|High-criticality allergy recorded|Allergie mit hoher Kritikalität erfasst|حساسية عالية الخطورة مسجلة")+" : "+crit.map((a?: A)=>a.substance).join(", "),sec:"allergies"});
   if(p.clin.allergyState?.state==="unknown"&&!dpAllergies(p).length)out.push({lvl:"warn",ic:"alert",t:L4("Statut allergique non documenté|Allergy status not documented|Allergiestatus nicht dokumentiert|حالة الحساسية غير موثقة"),sec:"allergies"});
   const dr=p.clin.enc.filter((e?: A)=>e.status==="draft");if(dr.length)out.push({lvl:"warn",ic:"pen",t:dr.length+" "+L4("consultation(s) en brouillon non signée(s)|unsigned draft consultation(s)|unsignierte Entwürfe|استشارة/استشارات مسودة غير موقعة"),sec:"enc"});
   p.clin.plans.filter((x?: A)=>dpLive(x)&&x.status==="active"&&x.review).forEach((x?: A)=>{const d=Math.round((+new Date(x.review+"T12:00:00")-+new Date(T+"T12:00:00"))/864e5);if(d<=14)out.push({lvl:d<0?"bad":"info",ic:"flow",t:(d<0?L4("Révision du plan dépassée|Plan review overdue|Planüberprüfung überfällig|تجاوز موعد مراجعة الخطة"):L4("Révision du plan prévue|Plan review due|Planüberprüfung fällig|مراجعة الخطة مستحقة"))+" — "+x.title+" ("+dpD(x.review)+")",sec:"plans"})});
   if(p.clin.plans.some((x?: A)=>dpLive(x)&&x.status==="active")&&!dpUpcoming(p,1).length)out.push({lvl:"info",ic:"cal",t:L4("Plan de soins actif sans rendez-vous à venir|Active care plan with no upcoming appointment|Aktiver Plan ohne kommenden Termin|خطة رعاية نشطة بلا موعد قادم"),sec:"appts",act:"book"})}
  const c=dpCompleteness(p);if(c.miss.length)out.push({lvl:"info",ic:"user",t:L4("Dossier administratif incomplet|Administrative record incomplete|Verwaltungsdaten unvollständig|الملف الإداري غير مكتمل")+" : "+c.miss.slice(0,3).map((m?: A)=>L4(m.l)).join(", ")+(c.miss.length>3?"…":""),sec:"info"});
  const b=dpBilling(p);if(b.state==="ok"&&b.over>0)out.push({lvl:"warn",ic:"coin",t:L4("Solde échu|Overdue balance|Überfälliger Saldo|رصيد متأخر")+" : "+dpMoney(b.over,b.cur),sec:"billing"});
  try{const pend=(p.consents||[]).filter((x?: A)=>x.state==="pending");if(pend.length)out.push({lvl:"info",ic:"shield",t:L4("Consentement en attente|Consent pending|Einwilligung ausstehend|موافقة قيد الانتظار")+" : "+pend.map((x?: A)=>L4(PA_CONSENT[x.type]||x.type)).join(", "),sec:"consents"})}catch(e){}
  return out}
