const dpStChip=(s?: A)=>{const k=({active:"ok",resolved:"mut",inactive:"mut",stopped:"mut",draft:"warn",signed:"ok",amended:"info",final:"ok",error:"bad",granted:"ok",refused:"bad",withdrawn:"mut",pending:"warn",confirmed:"ok"} as A)[s]||"mut";const l=({draft:"Brouillon|Draft|Entwurf|مسودة",signed:"Signée|Signed|Signiert|موقعة",amended:"Signée + addendum|Signed + addendum|Signiert + Nachtrag|موقعة + ملحق",final:"Finalisée|Final|Abgeschlossen|نهائي"} as A)[s];return dpChip(l?L4(l):L4(PA_ESTATE[s]||PA_CSTATE[s]||s||"—"),k)};
function dpCounts(p?: A){const clin=dpClin(p);const c={docs:dpDocs(p).length,appts:dpUpcoming(p).length};if(clin)Object.assign(c,{problems:p.clin.problems.filter((x?: A)=>dpLive(x)&&x.status==="active").length,allergies:dpAllergies(p).length,meds:dpMeds(p).length,enc:p.clin.enc.filter(dpLive).length,assess:p.clin.assess.filter(dpLive).length,plans:p.clin.plans.filter(dpLive).length+p.clin.therapy.length,hist:p.clin.hist.filter(dpLive).length,results:p.clin.obs.filter(dpLive).length+p.clin.labs.filter(dpLive).length+p.clin.imaging.filter(dpLive).length});return c}
const dpSince=(p?: A)=>{const c=[...(p.ids||[]).map((i?: A)=>i.since),...(p.hist||[]).map((h?: A)=>h.d),String(p.created||"").slice(0,10)].filter(x=>/^\d{4}-\d\d-\d\d$/.test(x||"")).sort();return c[0]||""};
const dpEstName=(p?: A)=>{try{return (rmEsts().find(e=>e.id===p.admin?.est)||{}).n||"—"}catch(e){return "—"}};
const dpLangName=(p?: A)=>{try{return new (Intl as any).DisplayNames([dpLocale()],{type:"language"}).of(p.lang||"fr").replace(/^./,(c?: A)=>c.toUpperCase())}catch(e){return p.lang||"—"}};
const dpBorn=(p?: A)=>{const L=true?lang():"fr";if(L==="fr")return p.sex==="F"?"Née le":p.sex==="M"?"Né le":"Né(e) le";return L4("Né(e) le|Born|Geboren am|تاريخ الميلاد")};
const dpAddr=(p?: A)=>{const a=p.contact?.addr||{};return [a.l1,[a.zip,a.city].filter(Boolean).join(" "),a.country].filter(Boolean).join(", ")};

