/* ---------- menus ---------- */
function dpMenu(btn?: A,items?: A){const R=dpRoot();R.querySelector(".dp-menu")?.remove();const m=document.createElement("div");m.className="dp-menu";m.setAttribute("role","menu");
  m.innerHTML=items.map((it?: A,i?: A)=>it==="-"?`<hr>`:`<button type="button" role="menuitem" data-mi="${i}"${it.dis?" disabled":""}>${dpI(it.ic||"chev",15)}<span>${dpE(it.l)}</span></button>`).join("");R.appendChild(m);
  const rb=R.getBoundingClientRect(),b=btn.getBoundingClientRect();const w=Math.min(260,rb.width-16);m.style.width=w+"px";const rtl=document.documentElement.dir==="rtl";let x=rtl?b.left-rb.left:b.right-rb.left-w;x=Math.max(8,Math.min(rb.width-w-8,x));m.style.left=x+"px";let y=b.bottom-rb.top+6;const mh=m.offsetHeight;if(y+mh>rb.height-8)y=Math.max(8,b.top-rb.top-mh-6);m.style.top=y+"px";
  if(!dpRM())m.animate([{opacity:0,transform:"translateY(-6px) scale(.97)"},{opacity:1,transform:"none"}],{duration:200,easing:"cubic-bezier(.2,1,.3,1)"});
  const close=()=>{m.remove();document.removeEventListener("pointerdown",out,true);btn.setAttribute("aria-expanded","false")};const out=(e?: A)=>{if(!m.contains((e.target as A))&&(e.target as A)!==btn&&!btn.contains((e.target as A)))close()};setTimeout(()=>document.addEventListener("pointerdown",out,true));btn.setAttribute("aria-expanded","true");
  m.onclick=e=>{const b2=(e.target as A).closest("[data-mi]");if(!b2)return;close();items[+b2.dataset.mi].fn()};m.onkeydown=e=>{const bs=[...m.querySelectorAll<A>("button:not([disabled])")];const i=bs.indexOf((document.activeElement as A));if(e.key==="ArrowDown"){bs[(i+1)%bs.length].focus();e.preventDefault()}if(e.key==="ArrowUp"){bs[(i-1+bs.length)%bs.length].focus();e.preventDefault()}if(e.key==="Escape"){close();btn.focus();e.stopPropagation()}};
  m.querySelector<A>("button:not([disabled])")?.focus()}
